import { readFile, writeFile } from "node:fs/promises";
// Each pair copies a source file into a TypeScript module the plugin ships as a string. The string is written one
// JSON line per source line, so git merges the generated file line by line exactly like its source: two PRs that
// touch different parts of agent-hook.mjs no longer collide in hook-source.ts. tests/generated-sources.test.ts keeps
// every generated file equal to its source.
const GENERATED = [
  ["server/mcp.mjs", "server/mcp-source.ts", "mcpSource"],
  ["server/agent-hook.mjs", "server/hook-source.ts", "hookSource"],
  ["server/overseer-prompt.md", "server/overseer-prompt-source.ts", "overseerPrompt"],
  ["server/wait-runner.sh", "server/wait-runner-source.ts", "runnerSource"],
  ["server/update-watchdog.mjs", "server/update-watchdog-source.ts", "watchdogSource"],
];
const at = path => new URL(`../${path}`, import.meta.url);
for (const [source, generated, name] of GENERATED) {
  const lines = (await readFile(at(source), "utf8")).split("\n").map(line => `  ${JSON.stringify(line)},`);
  await writeFile(at(generated), `// Generated by scripts/build.mjs from ${source}. Edit the source, then run node scripts/build.mjs.\nexport const ${name}: string = [\n${lines.join("\n")}\n].join("\\n");\n`);
}
